import java.util.List;
import java.util.stream.Collectors;

/**
 * TASK: Use the three-argument Collectors.joining(separator, prefix, suffix)
 * to wrap joined text without any manual string surgery.
 *
 * bracket(names): ", " between the names, "[" in front, "]" behind.
 *   bracket(["ann", "bo"]) -> "[ann, bo]"
 *   bracket([])            -> "[]"        (prefix and suffix are still added)
 *
 * inClause(ids): an SQL fragment with ", " between the ids, "IN (" in front
 * and ")" behind. The ids arrive as Integers and must be turned into text.
 *   inClause([3, 1, 4]) -> "IN (3, 1, 4)"
 *   inClause([])        -> "IN ()"
 */
public class BracketJoiner {

    public static String bracket(List<String> names) {
        return names.stream().collect(Collectors.joining(", ", "[", "]"));
    }

    public static String inClause(List<Integer> ids) {
        return ids.stream()
                .map(String::valueOf)
                .collect(Collectors.joining(", ", "IN (", ")"));
    }
}
